#!/usr/bin/env node
// Build docs/module/transcript.html — the full lecture transcript as accessible
// HTML, from the publisher transcript PDF (MIT OCW, human-made).
// The transcript text is parsed from scripts/caption-build/transcript.txt
// (generated by scripts/build-captions.mjs, which extracts it from the PDF).
// Speaker labels and paragraph breaks are preserved; cue timestamps from
// docs/module/media/captions-en.vtt are shown per paragraph for orientation.
// Run: node scripts/build-transcript.mjs

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const WORK = join(ROOT, "scripts", "caption-build");
const transcriptTxt = join(WORK, "transcript.txt");
if (!existsSync(transcriptTxt)) {
  execFileSync("python3", ["-c", `
from pypdf import PdfReader
r = PdfReader(${JSON.stringify(join(ROOT, "source", "ocw-transcript-lec01.pdf"))})
open(${JSON.stringify(transcriptTxt)}, "w").write("\\n\\n".join((p.extract_text() or "") for p in r.pages))
`]);
}

let raw = readFileSync(transcriptTxt, "utf8");
// split off MITOCW header; the CC blurb is spoken (narrator) so it starts the transcript
const headerMatch = raw.match(/^MITOCW \|.*$/m);
let blurb = "";
if (headerMatch) {
  const after = raw.slice(headerMatch.index + headerMatch[0].length);
  const fsRel = after.search(/^[A-Z][A-Z ]+:\s*$/m);
  blurb = after.slice(0, fsRel).replace(/\s+/g, " ").trim();
  raw = after.slice(fsRel);
}

const paragraphs = [];
let speaker = "Narrator", buf = [];
if (blurb) paragraphs.push({ speaker: "Narrator", text: blurb });
for (const line of raw.split("\n")) {
  const s = line.trim();
  const sp = s.match(/^([A-Z][A-Z ]+):$/);
  if (sp) {
    if (buf.length) paragraphs.push({ speaker, text: buf.join(" ") });
    speaker = sp[1][0] + sp[1].slice(1).toLowerCase();
    buf = [];
    continue;
  }
  if (!s) { if (buf.length) { paragraphs.push({ speaker, text: buf.join(" ") }); buf = []; } continue; }
  buf.push(s);
}
if (buf.length) paragraphs.push({ speaker, text: buf.join(" ") });

// drop trailing page-number artifacts (standalone digits)
while (paragraphs.length && /^\d+$/.test(paragraphs[paragraphs.length - 1].text.trim())) paragraphs.pop();

// map cue start times onto paragraphs: build cue list from the VTT, then assign
// each paragraph the cue timestamp whose text best matches the paragraph head
const vtt = readFileSync(join(ROOT, "docs", "module", "media", "captions-en.vtt"), "utf8");
const cueRe = /(\d{2}):(\d{2}):([\d.]+)\n([^\n]+)/g;
const cues = [];
let m;
while ((m = cueRe.exec(vtt))) {
  cues.push({ t: (+m[1]) * 3600 + (+m[2]) * 60 + parseFloat(m[3]), text: m[4].replace(/^[A-Z]+:\s*/, "") });
}
const norm = (s) => s.toLowerCase().replace(/[^a-z0-9 ]/g, "").replace(/\s+/g, " ").trim();
const cueNorm = cues.map((c) => norm(c.text));

function paraStart(pText) {
  const head = norm(pText).slice(0, 60);
  for (let i = 0; i < cueNorm.length; i++) {
    if (cueNorm[i].includes(head.slice(0, 30)) && head.length > 10) return cues[i].t;
  }
  // fallback: first cue that shares its first 4 words
  const words = head.split(" ").slice(0, 4).join(" ");
  for (let i = 0; i < cueNorm.length; i++) if (cueNorm[i].startsWith(words) && words.length > 6) return cues[i].t;
  return null;
}

const fmt = (s) => {
  if (s === null) return "";
  const h = Math.floor(s / 3600), mn = Math.floor((s % 3600) / 60), sc = Math.floor(s % 60);
  return `${h}:${String(mn).padStart(2, "0")}:${String(sc).padStart(2, "0")}`;
};

let body = "";
let lastSpeaker = null;
for (const p of paragraphs) {
  const ts = paraStart(p.text);
  const label = p.speaker !== lastSpeaker
    ? `<strong class="spk">${p.speaker}:</strong> `
    : "";
  lastSpeaker = p.speaker;
  body += `<p><span class="meta">[${ts !== null ? fmt(ts) : "—"}]</span> ${label}${p.text}</p>\n`;
}

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Lecture 1 transcript — Unit 1 | Accessibility Remediation Case Study</title>
<link rel="stylesheet" href="css/module.css">
</head>
<body>
<a class="skip-link" href="#main">Skip to main content</a>
<header class="site-header">
  <div class="wrap">
    <p class="site-kicker">Unit 1 · Introduction to Psychology — remediated module</p>
    <p class="site-title"><a href="index.html">Introduction to Psychology — Unit 1: Introduction</a></p>
    <nav class="site-nav" aria-label="Module pages">
      <ul>
        <li><a href="index.html">Overview</a></li>
        <li><a href="lesson.html">Lesson</a></li>
        <li><a href="slides.html">Lecture slides</a></li>
        <li><a href="video.html">Video</a></li>
        <li><a href="transcript.html" aria-current="page">Transcript</a></li>
        <li><a href="quiz.html">Quiz</a></li>
        <li><a href="../index.html">Case study home</a></li>
      </ul>
    </nav>
  </div>
</header>
<main id="main" tabindex="-1">
<div class="wrap">

<h1>Lecture 1 transcript</h1>
<p class="lede">Full transcript of <cite>Lecture 1: Introduction</cite>
(≈ 50 minutes), spoken by Prof. John Gabrieli. Timestamps are approximate cue
starts from the <a href="video.html">video page’s captions</a>.</p>

<div class="note">
<p><strong>Source.</strong> The transcript text is MIT OpenCourseWare’s official
human transcript for this lecture (retrieved from the lecture’s resource page,
2026-10-25), converted to HTML. The original module page linked no transcript at
all. A video-only alternative like this page also supports people who are
deaf-blind, anyone who prefers reading, and search. Bracketed times are
approximate.</p>
</div>

${body}

</div>
</main>
<footer class="site-footer">
  <div class="wrap">
    <p>Remediated module for the case study “Accessibility remediation of a real
    course module.” Content adapted from <em>9.00SC Introduction to Psychology,
    Fall 2011</em> (Unit&nbsp;1) by Prof. John Gabrieli, MIT OpenCourseWare,
    licensed CC BY-NC-SA 3.0 US; this adaptation is licensed alike (see
    <a href="../index.html#attribution">attribution</a>).
    “Lakeside State University” is a fictional US public university preparing for
    ADA Title II digital accessibility compliance.</p>
  </div>
</footer>
</body>
</html>
`;

const out = join(ROOT, "docs", "module", "transcript.html");
writeFileSync(out, html);
console.log(`wrote ${out} with ${paragraphs.length} paragraphs`);
